using System.Runtime.InteropServices;
namespace LSE.AutoCADElectrical.ProjectDoctor;
public static class DiagnosticsService{
 public static string BuildReport(){var s=SettingsService.Load();var x=new List<string>{"LSE_Doctor diagnostics  "+DateTime.Now.ToString("s"),"Build: "+BuildInfo.Release,RuntimeInformation.FrameworkDescription,"Assembly: "+typeof(DiagnosticsService).Assembly.Location,"Settings: "+SettingsService.SettingsPath,"Template project: "+s.TemplateProjectPath+(File.Exists(s.TemplateProjectPath)?" (exists)":" (MISSING - the bundled copy is used)"+(VaultProbe.InVaultWorkingFolder(s.TemplateProjectPath)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":"")),"Bundled standard: "+(SettingsService.BundledStandardWdp()??"none in "+SettingsService.BundledStandardFolder),"Rules JSON: "+s.RulesConfigPath+(File.Exists(s.RulesConfigPath)?" (exists)":" (MISSING - built-in defaults)"),"Projects root (scan default): "+s.ProjectsRootFolder+(Directory.Exists(s.ProjectsRootFolder)?" (exists)":" (MISSING)")+(VaultProbe.InVaultWorkingFolder(s.ProjectsRootFolder)?" (inside the Vault working folder: files that are not checked out are read-only)":""),"Backups: <project>\\"+s.BackupFolderName+"\\<timestamp>, keep "+s.BackupsToKeep,"Check drawings: "+s.CheckDrawings+", insert missing WD_M: "+s.InsertMissingWdm+", scan checks drawings: "+s.ScanChecksDrawings,"Active project LISP: "+s.ActiveProjectLisp,"Reload project LISP: "+s.ActivateProjectLisp};
  DoctorRules? r=null;try{r=RulesService.Load(s.RulesConfigPath);x.Add($"Rules: PASS (path list mode {r.PathListMode}; enforce options {r.EnforceOptions}, properties {r.EnforceProperties}, labels {r.EnforceLabels}, mappings {r.EnforceMappings}; protected +[{string.Join(",",r.ProtectedOptions)}] ?[{string.Join(",",r.ProtectedProperties)}])");}catch(Exception ex){x.Add("Rules: FAIL "+ex.Message);}
  if(r is not null)try{var std=StandardService.Load(s,r);x.Add($"Standard: PASS {std.WdpPath}{(std.Bundled?" (bundled copy)":"")}");x.Add($"Standard .wdp: {std.Descriptions.Count} description, {std.Options.Count} option, {std.Properties.Count} property line(s), {std.DrawingPaths.Count} drawing(s), {TextFileService.EncodingName(std.Wdp.Encoding)}");x.Add("Standard .wdt: "+(std.Wdt is null?"NONE (mapping check skipped)":std.Wdt.Path+$" ({std.Mappings.Count} mapping(s); title block(s): {string.Join(", ",std.TitleBlockNames)})"));x.Add("Standard .wdl: "+(std.Wdl is null?"NONE (label check skipped)":std.Wdl.Path+$" ({std.Labels.Count} label(s))"));x.Add("Template drawing (WD_M source): "+(std.TemplateDrawingPath.Length==0?"NONE (WD_M insertion unavailable)"+(VaultProbe.InVaultWorkingFolder(s.TemplateProjectPath)?" - not downloaded yet? In Vault Explorer select the folder and Get Latest Version":""):std.TemplateDrawingPath));}catch(Exception ex){x.Add("Standard: FAIL "+ex.Message);}
  x.Add(VaultProbe.Report(""));x.Add("Recent projects: "+s.RecentProjects.Count);return string.Join(Environment.NewLine,x);}
}
